"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, decide


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order_changes(changes):
    """Return the deterministic topological order of all change IDs.

    Among currently eligible changes the lexicographically smallest ID runs first.
    """
    dependents = {change_id: [] for change_id in changes}
    pending = {}
    for change_id, change in changes.items():
        targets = set()
        for dependency in change["depends_on"]:
            if dependency not in changes:
                raise JournalError("unknown-dependency")
            targets.add(dependency)
        pending[change_id] = len(targets)
        for dependency in targets:
            dependents[dependency].append(change_id)
    eligible = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        _environment, action, budget = decide(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), changes)
        order = order_changes(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if action == "rollback":
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(changes[change_id]["units"] for change_id in actions)
        if units > budget:
            return failure("budget-exceeded")
    units = sum(changes[change_id]["units"] for change_id in actions)
    return {"status": "ok", "actions": actions, "units": units}

