"""Normalize release records at the input boundary.

Responsibility: validation, identity and replay data for change records.
This module never sorts; ordering lives in planner.py.
"""
from collections import Counter


class JournalError(ValueError):
    pass


def _is_id(value):
    # ``type(...) is str`` deliberately rejects str subclasses that also compare oddly;
    # more importantly, non-strings here would break dict keys used for graph lookup.
    return type(value) is str and value != ""


def _read_dependencies(row):
    """Return the dependency set for one record, or raise invalid-change.

    ``depends_on`` defaults to an empty list. Order does not matter, so we keep a frozenset:
    duplicate/re-ordered dependency lists must not make two otherwise equal records "conflict".
    """
    raw = row.get("depends_on", [])
    if not isinstance(raw, list):
        raise JournalError("invalid-change")
    deps = set()
    for dep in raw:
        if not _is_id(dep):
            raise JournalError("invalid-change")
        deps.add(dep)
    return frozenset(deps)


def read_changes(records):
    """Validate raw change records and collapse duplicates.

    The result is a list of ``{"id", "component", "units", "dependencies"}`` tuples-like dicts
    in first-seen order. Duplicate IDs:
      * identical identity (component, units, dependency set) -> collapse to one;
      * otherwise -> "conflicting-change".
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    by_id = {}
    order = []
    for row in records:
        if (not isinstance(row, dict) or not _is_id(row.get("id"))
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        deps = _read_dependencies(row)
        change = {"id": row["id"], "component": row["component"],
                  "units": row["units"], "dependencies": deps}
        previous = by_id.get(change["id"])
        if previous is None:
            by_id[change["id"]] = change
            order.append(change["id"])
        elif (previous["component"], previous["units"], previous["dependencies"]) != (
                change["component"], change["units"], change["dependencies"]):
            raise JournalError("conflicting-change")
        # Identical duplicates: keep the first occurrence, ignore the rest.
    return [by_id[change_id] for change_id in order]


def read_applied(raw, known_ids):
    """Validate the caller-supplied ``applied`` journal against known change IDs.

    Returns a set of applied IDs. Unknown IDs (and malformed input) are rejected here
    rather than in the planner so that every journal-shaped input error is
    "invalid-change"/"unknown-dependency" regardless of where it is discovered.
    """
    if raw is None:
        return set()
    if not isinstance(raw, list):
        raise JournalError("invalid-change")
    applied = set()
    for change_id in raw:
        if not _is_id(change_id):
            raise JournalError("invalid-change")
        applied.add(change_id)
    unknown = applied - set(known_ids)
    if unknown:
        raise JournalError("unknown-dependency")
    return applied


def check_targets(changes):
    """Reject dependencies that do not name a change in this request.

    Must run before graph construction: a missing node would otherwise silently
    drop an edge and produce an ordering that violates the caller's intent.
    """
    known = {change["id"] for change in changes}
    for change in changes:
        if change["dependencies"] - known:
            raise JournalError("unknown-dependency")

