"""Compose policy and journal data into a plan.

Ordering here is the deterministic topological order consumed by both actions:
``plan`` replays forward over it, ``rollback`` walks it backwards.
"""
import heapq
from collections import defaultdict

from journal import JournalError, check_targets, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking among currently eligible nodes.

    A ready set is not enough: SPEC asks for the lexicographically smallest ID *among nodes
    eligible right now*, so we keep a min-heap and pull one node at a time. Sorting each
    "level" together, or a DFS post-order, gives a different (still valid-looking) order and
    would drift from the spec.

    Returns None when a cycle exists, which the caller maps to "dependency-cycle".
    A record depending on itself is a one-node cycle and is caught by the same check.
    """
    ids = [change["id"] for change in changes]
    in_degree = dict.fromkeys(ids, 0)
    dependents = defaultdict(list)
    for change in changes:
        for dependency in change["dependencies"]:
            # Edge dependency -> change; target existence was checked by check_targets.
            dependents[dependency].append(change["id"])
            in_degree[change["id"]] += 1

    ready = [change_id for change_id in ids if in_degree[change_id] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(ids):
        return None
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Validation order is intentional and covered by tests: structural policy errors
        # first, then record/journal semantics, then the budget. SPEC fixes the codes but
        # not their precedence, so we pin one to keep behaviour stable across sessions.
        budget = limit_for(request)
        action = request["action"]
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), [c["id"] for c in changes])
        check_targets(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    order = topological_order(changes)
    if order is None:
        return failure("dependency-cycle")

    units_by_id = {change["id"]: change["units"] for change in changes}
    if action == "plan":
        # Replay: applied entries satisfy dependencies for free (they already succeeded),
        # so they are skipped from the budget sum. Deduplication already happened above,
        # which is why duplicated identical records cannot inflate this total.
        emitted = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
        if units > budget:
            return failure("budget-exceeded")
    else:
        # Rollback undoes applied changes in the exact reverse of the *full* forward order;
        # unapplied changes are filtered out afterwards so their neighbours cannot be
        # reordered relative to each other. Budget is validated but never compared here.
        emitted = [change_id for change_id in reversed(order) if change_id in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
    return {"status": "ok", "actions": emitted, "units": units}

