"""Compose policy and journal data into a plan.

Ordering here is the deterministic topological order consumed by both actions:
``plan`` replays forward over it, ``rollback`` walks it backwards.
"""
import heapq
from collections import defaultdict

from journal import JournalError, check_targets, read_applied, read_changes, read_retain
from policy import PolicyError, effective_budget, environment_of, frozen_error, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking among currently eligible nodes.

    A ready set is not enough: SPEC asks for the lexicographically smallest ID *among nodes
    eligible right now*, so we keep a min-heap and pull one node at a time. Sorting each
    "level" together, or a DFS post-order, gives a different (still valid-looking) order and
    would drift from the spec.

    Returns None when a cycle exists, which the caller maps to "dependency-cycle".
    A record depending on itself is a one-node cycle and is caught by the same check.
    """
    ids = [change["id"] for change in changes]
    in_degree = dict.fromkeys(ids, 0)
    dependents = defaultdict(list)
    for change in changes:
        for dependency in change["dependencies"]:
            # Edge dependency -> change; target existence was checked by check_targets.
            dependents[dependency].append(change["id"])
            in_degree[change["id"]] += 1

    ready = [change_id for change_id in ids if in_degree[change_id] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(ids):
        return None
    return order


def retained_closure(changes, applied, retained):
    """Return the retained IDs plus the applied dependencies they transitively require.

    Rolling back a change breaks whatever depended on it, so keeping ``retained`` alive
    means every *applied* change it (directly or indirectly) depends on must stay too.
    We walk ``dependencies`` upwards and stop at IDs that are not applied: an unapplied
    change is not a rollback candidate anyway, so it cannot be broken by us, and there is
    nothing above it to protect. (Deliberately not an error -- SPEC does not require the
    "applied dependencies are applied" invariant; see ARCHITECTURE.md §7.)

    Only reachability from the retained set matters, never the forward order.
    """
    dependencies = {change["id"]: change["dependencies"] for change in changes}
    keep = set(retained)
    stack = list(retained)
    while stack:
        current = stack.pop()
        for dependency in dependencies[current]:
            if dependency in applied and dependency not in keep:
                keep.add(dependency)
                stack.append(dependency)
    # ``dependencies`` is a DAG here: the planner only calls this after a cycle check,
    # so the walk terminates. ``keep`` also guards against re-pushing shared dependencies.
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Freeze gate before anything else: a production request must report
        # production-frozen even when ``changes``/``budget`` are malformed or the graph is
        # cyclic (CHANGE-G2 rule 1). It reads only "environment", so it needs no other field.
        environment = environment_of(request)
        frozen = frozen_error(environment)
    except PolicyError as exc:
        return failure(str(exc))
    if frozen is not None:
        return failure(frozen)

    try:
        # Validation order is intentional and covered by tests: structural policy errors
        # first, then record/journal semantics, then the budget. SPEC fixes the codes but
        # not their precedence, so we pin one to keep behaviour stable across sessions.
        budget = limit_for(request)
        action = request["action"]
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), [c["id"] for c in changes])
        check_targets(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    order = topological_order(changes)
    if order is None:
        return failure("dependency-cycle")

    units_by_id = {change["id"]: change["units"] for change in changes}
    if action == "plan":
        # Replay: applied entries satisfy dependencies for free (they already succeeded),
        # so they are skipped from the budget sum. Deduplication already happened above,
        # which is why duplicated identical records cannot inflate this total.
        emitted = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
        # Compare against the *effective* ceiling: staging caps every request at
        # STAGING_BUDGET_CAP, so "budget=99, units=4" is still budget-exceeded.
        # ``retain`` is rollback-only and is intentionally not read here.
        if units > effective_budget(environment, action, budget):
            return failure("budget-exceeded")
    else:
        try:
            # Read after the graph is known valid, so a cyclic request still reports
            # dependency-cycle rather than a retain shape error.
            retained = read_retain(request.get("retain", []), applied)
        except JournalError as exc:
            return failure(str(exc))
        keep = retained_closure(changes, applied, retained)
        # Rollback undoes applied changes in the exact reverse of the *full* forward order;
        # unapplied changes and retained ones are filtered out afterwards so their
        # neighbours cannot be reordered relative to each other. Budget is validated but
        # never compared here.
        emitted = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in keep]
        units = sum(units_by_id[change_id] for change_id in emitted)
    return {"status": "ok", "actions": emitted, "units": units}

