import json


class JournalError(ValueError):
    pass


def _key(value):
    """Stable hashable form used to compare dependencies as a set."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def _read_id_list(value):
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    ids = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        ids.append(item)
    return ids


def _read_dependencies(row):
    if "depends_on" not in row:
        return []
    return sorted({_key(item) for item in _read_id_list(row["depends_on"])})


def read_changes(records):
    """Validate records and collapse equal duplicates, preserving first-seen order."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        dependencies = _read_dependencies(row)
        signature = (row["component"], row["units"], tuple(dependencies))
        previous = seen.get(row["id"])
        if previous is None:
            seen[row["id"]] = signature
            changes.append({"id": row["id"], "component": row["component"],
                            "units": row["units"], "dependencies": dependencies})
        elif previous != signature:
            raise JournalError("conflicting-change")
    return changes


def read_applied(values):
    """Validate the persisted release journal and return its unique IDs in order."""
    applied = []
    seen = set()
    for change_id in _read_id_list(values):
        if change_id not in seen:
            seen.add(change_id)
            applied.append(change_id)
    return applied

