            seen.add(change_id)
            applied.append(change_id)
    return applied


def read_retain(request):
    """Validate the rollback retain list and return its unique IDs.

    `retain` defaults to an empty list. Only the shape of the list is checked
    here; whether each ID is applied is resolved against the journal later.
    """
    if "retain" not in request:
        return []
