"""Compose policy and journal data into a plan."""
import heapq
import json

from journal import RetainError, JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for

NO_ACTIONS = []


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _target_id(dependency):
    """Return the change ID named by a dependency, or None when it cannot name one."""
    try:
        value = json.loads(dependency)
    except ValueError:
        return None
    return value if isinstance(value, str) and value else None


def _graph(changes, applied):
    """Validate references and return (topological order, full dependency edges).

    Every change must be reachable, so references to unknown or malformed
    dependency targets fail here. The returned edges keep dependencies on
    applied changes: rollback needs the full graph to find transitive
    dependencies, while ordering walks only edges that remain unsatisfied.
    """
    by_id = {change["id"]: change for change in changes}
    for change_id in applied:
        if change_id not in by_id:
            raise JournalError("unknown-dependency")

    edges = {}
    for change in changes:
        targets = []
        for dependency in change["dependencies"]:
            target = _target_id(dependency)
            if target is None or target not in by_id:
                raise JournalError("unknown-dependency")
            targets.append(target)
        edges[change["id"]] = targets

    # Dependencies on applied changes are satisfied by the journal, so they
    # leave no edge when ordering.
    live = {change_id: [t for t in targets if t not in applied]
            for change_id, targets in edges.items()}
    indegree = {change_id: len(targets) for change_id, targets in live.items()}
    dependents = {change["id"]: [] for change in changes}
    for change_id, targets in live.items():
        for target in targets:
            dependents[target].append(change_id)

    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order, edges


def _retained(applied_set, retain, edges):
    """Return the applied changes that rollback must keep.

    G2: "Retain the transitive dependencies that are applied and required by
    those retained changes." The kept set is therefore the requested IDs plus
    the applied dependencies they reach transitively. Rollback never emits a
    kept ID.
    """
    kept = set()
    pending = list(retain)
    while pending:
        current = pending.pop()
        if current in kept:
            continue
        kept.add(current)
        for target in edges[current]:
            if target in applied_set and target not in kept:
                pending.append(target)
    return kept


def _select(request, budget):
    changes = read_changes(request.get("changes"))
    applied_input = request.get("applied")
    applied = read_applied([] if applied_input is None else applied_input)
    action = request["action"]
    retain = read_retain(request) if action == "rollback" else []
    applied_set = set(applied)
    order, edges = _graph(changes, applied_set)
    by_id = {change["id"]: change for change in changes}
    if action == "plan":
        actions = [change_id for change_id in order if change_id not in applied_set]
        units = sum(by_id[change_id]["units"] for change_id in actions)
        if units > budget:
            return failure("budget-exceeded")
        return {"status": "ok", "actions": actions, "units": units}
    for change_id in retain:
        if change_id not in applied_set:
            raise RetainError()
    kept = _retained(applied_set, retain, edges)
    actions = [change_id for change_id in reversed(order)
               if change_id in applied_set and change_id not in kept]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    return {"status": "ok", "actions": actions, "units": units}

def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        return _select(request, budget)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

