"""Normalize release records at the input boundary.

Responsibilities: input validation, record identity (dedup/conflict), the
persisted ``applied`` journal, and the deterministic dependency order.
No budgeting here -- policy owns budgets, planner decides what gets emitted.
"""
import heapq


class JournalError(ValueError):
    """Carries one of the SPEC error codes as its message."""


def _is_nonempty_str(value):
    return isinstance(value, str) and value != ""


def _string_list(value, code):
    """Validate a list of IDs.

    Non-arrays and malformed entries are ``invalid-change`` (SPEC line 12).
    Booleans never count as strings, but ``isinstance`` is enough here since
    JSON ``true`` is a ``bool``, not a ``str``.
    """
    if not isinstance(value, list):
        raise JournalError(code)
    for item in value:
        # An empty name is treated as malformed rather than as an unknown ID:
        # it can only ever produce a less specific error.
        if not _is_nonempty_str(item):
            raise JournalError(code)
    return value


def read_changes(records):
    """Validate and deduplicate change records.

    Returns a list of ``{"id", "component", "units", "depends_on"}`` dicts in
    first-seen order with ``depends_on`` normalized to a *set*. Equivalence
    covers id, component, units and the dependency *set*, so ordering or
    repeated names inside ``depends_on`` do not make two records different.
    A second record with the same id but different content is a conflict.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    seen = {}
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not _is_nonempty_str(row.get("id"))
                # ``type(...) is int`` (not isinstance): JSON true/false are
                # Python bools, which are ints, and SPEC excludes booleans.
                or not _is_nonempty_str(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        # ``depends_on`` defaults to empty; an explicit JSON null is malformed
        # (only lists are accepted), hence no None fallback here.
        depends_on = row.get("depends_on", [])
        record = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(_string_list(depends_on, "invalid-change")),
        }
        previous = seen.get(record["id"])
        if previous is None:
            seen[record["id"]] = record
            changes.append(record)
        elif previous != record:
            raise JournalError("conflicting-change")
        # else: identical duplicate collapses to one record (already emitted).
    return changes


def read_applied(value):
    """Validate the caller-supplied persisted release journal.

    Returns a set of IDs. Malformed input is ``invalid-change``; unknown IDs
    are checked by the planner against the change records so this function
    stays independent of the graph.
    """
    return frozenset(_string_list(value if value is not None else [], "invalid-change"))


def check_dependencies(changes):
    """Every ``depends_on`` entry must name a change in this request."""
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            # Ids are compared verbatim: no trimming or case folding, on the
            # assumption that the caller's IDs are already canonical.
            if dependency not in known:
                raise JournalError("unknown-dependency")


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking.

    The ready set is a min-heap keyed by ID, so among all currently eligible
    changes the lexicographically smallest is emitted first. The result does
    not depend on input order, which is what makes ``plan`` and ``rollback``
    reproducible across runs.
    """
    indegree = {row["id"]: len(row["depends_on"]) for row in changes}
