    """Every ``depends_on`` entry must name a change in this request."""
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            # Ids are compared verbatim: no trimming or case folding, on the
            # assumption that the caller's IDs are already canonical.
            if dependency not in known:
                raise JournalError("unknown-dependency")


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking.

    The ready set is a min-heap keyed by ID, so among all currently eligible
    changes the lexicographically smallest is emitted first. The result does
    not depend on input order, which is what makes ``plan`` and ``rollback``
    reproducible across runs.
    """
    indegree = {row["id"]: len(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            dependents[dependency].append(row["id"])
    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        # Nodes left over are exactly those reachable from / inside a cycle.
        raise JournalError("dependency-cycle")
    return order


def retained_ids(changes, applied, retain):
    """G2-3: the applied IDs a staging rollback must leave in place.

    ``retain`` is the caller's request field (``None``/absent -> empty). Every
    listed ID must be a change in this request *and* already applied: retention
    of something that is not installed has no meaning, so both cases are
    ``invalid-retain`` rather than a silently ignored entry.

    Returns the retained set, closed over dependencies transitively. The
    closure deliberately stops at dependencies that are not applied: G2 only
    asks for "the transitive dependencies that are applied", and requiring the
    rest would make ``retain`` unusable whenever the journal is partial.
    """
    if retain is None:
        # Absent or explicit JSON null: G2 defaults ``retain`` to empty. This is
        # the one place a null is tolerated instead of being malformed.
        return frozenset()
    try:
        requested = _string_list(retain, "invalid-retain")
    except JournalError:
        # Malformed lists must not surface as invalid-change: G2 gives the
        # retain field its own code, and it is read only on rollback.
        raise JournalError("invalid-retain") from None
    known = {row["id"]: row for row in changes}
    for change_id in requested:
        if change_id not in known or change_id not in applied:
            raise JournalError("invalid-retain")
    retained = set()
    pending = list(requested)
    while pending:
        change_id = pending.pop()
        if change_id in retained:
            continue  # diamond joins revisit nodes; stop instead of recursing
        retained.add(change_id)
        for dependency in known[change_id]["depends_on"]:
            if dependency in applied and dependency not in retained:
                pending.append(dependency)
    return frozenset(retained)

